                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        if (tagInput.trim() && !config.tags?.includes(tagInput.trim())) {
                          setConfig({ 
                            ...config, 
                            tags: [...(config.tags || []), tagInput.trim()] 
                          });
                          setTagInput("");
                        }
                      }}
