                  {config.tags && config.tags.length > 0 && (
                    <div className="flex flex-wrap gap-2 mt-2">
                      {config.tags.map((tag, index) => (
                        <Badge key={index} variant="secondary" className="gap-1">
                          {tag}
                          <button
