import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Zap, Plus, Play, Clock, CheckCircle, XCircle, Edit, Trash2, History, Calendar, AlertCircle } from "lucide-react";
import { useState } from "react";
import { WorkflowEditor } from "@/components/workflow-editor";
import { useToast } from "@/hooks/use-toast";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { ScrollArea } from "@/components/ui/scroll-area";

type Workflow = {
  id: string;
  name: string;
  description: string;
  triggerType: "manual" | "scheduled" | "webhook";
  triggerSchedule: string | null;
  enabled: boolean;
  steps: any[];
  createdAt: string;
  updatedAt: string;
};

type WorkflowRun = {
  id: string;
  workflowId: string;
  status: "running" | "completed" | "failed";
  startedAt: string;
  completedAt: string | null;
  error: string | null;
  input?: any;
  output?: any;
};

export default function WorkflowsPage() {
  const { toast } = useToast();
  const [showEditor, setShowEditor] = useState(false);
  const [editingWorkflow, setEditingWorkflow] = useState<Workflow | null>(null);
  const [deleteWorkflowId, setDeleteWorkflowId] = useState<string | null>(null);
  const [viewRunsWorkflowId, setViewRunsWorkflowId] = useState<string | null>(null);

  const { data: workflows = [], isLoading } = useQuery<Workflow[]>({
    queryKey: ["/api/workflows"],
  });

  const { data: workflowRuns = [], isLoading: isLoadingRuns } = useQuery<WorkflowRun[]>({
    queryKey: ["/api/workflows", viewRunsWorkflowId, "runs"],
    enabled: !!viewRunsWorkflowId,
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      await apiRequest("DELETE", `/api/workflows/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/workflows"] });
      toast({
        title: "Workflow deleted",
        description: "The workflow has been deleted successfully.",
      });
      setDeleteWorkflowId(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete workflow",
        variant: "destructive",
      });
    },
  });

  const executeMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await apiRequest("POST", `/api/workflows/${id}/execute`, { input: {} });
      return await response.json();
    },
    onSuccess: (data: any) => {
      toast({
        title: "Workflow executed",
        description: `Run ID: ${data.id} - Status: ${data.status}`,
      });
      queryClient.invalidateQueries({ queryKey: ["/api/workflows"] });
    },
    onError: (error: any) => {
      toast({
        title: "Execution failed",
        description: error.message || "Failed to execute workflow",
        variant: "destructive",
      });
    },
  });

  const handleCreateWorkflow = () => {
    setEditingWorkflow(null);
    setShowEditor(true);
  };

  const handleEditWorkflow = (workflow: Workflow) => {
    setEditingWorkflow(workflow);
    setShowEditor(true);
  };

  const handleCloseEditor = () => {
    setShowEditor(false);
    setEditingWorkflow(null);
  };

  if (showEditor) {
    return <WorkflowEditor workflow={editingWorkflow} onClose={handleCloseEditor} />;
  }

  return (
    <div className="h-full overflow-auto">
      <div className="max-w-7xl mx-auto p-6 space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <Zap className="w-8 h-8 text-primary" />
              Workflow Automation
            </h1>
            <p className="text-muted-foreground mt-1">
              Chain AI tasks together to automate complex workflows
            </p>
          </div>
          <Button onClick={handleCreateWorkflow} data-testid="button-create-workflow">
            <Plus className="w-4 h-4 mr-2" />
            Create Workflow
          </Button>
        </div>

        {isLoading ? (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <Card key={i} className="animate-pulse">
                <CardHeader>
                  <div className="h-5 bg-muted rounded w-3/4" />
                  <div className="h-4 bg-muted rounded w-full mt-2" />
                </CardHeader>
                <CardContent>
                  <div className="h-4 bg-muted rounded w-1/2" />
                </CardContent>
              </Card>
            ))}
          </div>
        ) : workflows.length === 0 ? (
          <Card>
            <CardContent className="flex flex-col items-center justify-center p-12">
              <Zap className="w-16 h-16 text-muted-foreground mb-4" />
              <h3 className="text-xl font-semibold mb-2">No workflows yet</h3>
              <p className="text-muted-foreground text-center mb-4">
                Create your first workflow to automate AI tasks
              </p>
              <Button onClick={handleCreateWorkflow} data-testid="button-create-first-workflow">
                <Plus className="w-4 h-4 mr-2" />
                Create Your First Workflow
              </Button>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {workflows.map((workflow) => (
              <Card key={workflow.id} data-testid={`card-workflow-${workflow.id}`}>
                <CardHeader>
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <CardTitle className="flex items-center gap-2">
                        {workflow.name}
                        <Badge
                          variant={workflow.enabled ? "default" : "secondary"}
                          data-testid={`badge-status-${workflow.id}`}
                        >
                          {workflow.enabled ? "Enabled" : "Disabled"}
                        </Badge>
                      </CardTitle>
                      <CardDescription className="mt-1">
                        {workflow.description || "No description"}
                      </CardDescription>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="space-y-3">
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <Clock className="w-4 h-4" />
                      <span className="capitalize">{workflow.triggerType} trigger</span>
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {workflow.steps?.length || 0} steps
                    </div>
                    <div className="flex gap-2 flex-wrap">
                      <Button
                        size="sm"
                        variant="default"
                        onClick={() => executeMutation.mutate(workflow.id)}
                        disabled={!workflow.enabled || executeMutation.isPending}
                        data-testid={`button-execute-${workflow.id}`}
                      >
                        <Play className="w-3 h-3 mr-1" />
                        Run
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => setViewRunsWorkflowId(workflow.id)}
                        data-testid={`button-view-runs-${workflow.id}`}
                      >
                        <History className="w-3 h-3 mr-1" />
                        Runs
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleEditWorkflow(workflow)}
                        data-testid={`button-edit-${workflow.id}`}
                      >
                        <Edit className="w-3 h-3 mr-1" />
                        Edit
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => setDeleteWorkflowId(workflow.id)}
                        data-testid={`button-delete-${workflow.id}`}
                      >
                        <Trash2 className="w-3 h-3 mr-1" />
                        Delete
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>

      <AlertDialog open={!!deleteWorkflowId} onOpenChange={() => setDeleteWorkflowId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Workflow</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this workflow? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deleteWorkflowId && deleteMutation.mutate(deleteWorkflowId)}
              data-testid="button-confirm-delete"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <Dialog open={!!viewRunsWorkflowId} onOpenChange={() => setViewRunsWorkflowId(null)}>
        <DialogContent className="max-w-4xl max-h-[80vh]">
          <DialogHeader>
            <DialogTitle>Workflow Run History</DialogTitle>
            <DialogDescription>
              View past executions and their results
            </DialogDescription>
          </DialogHeader>
          <ScrollArea className="h-[60vh] pr-4">
            {isLoadingRuns ? (
              <div className="space-y-4">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="border rounded-lg p-4 animate-pulse">
                    <div className="h-4 bg-muted rounded w-1/4 mb-2" />
                    <div className="h-3 bg-muted rounded w-1/2" />
                  </div>
                ))}
              </div>
            ) : workflowRuns.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12">
                <History className="w-12 h-12 text-muted-foreground mb-4" />
                <p className="text-muted-foreground">No runs yet</p>
              </div>
            ) : (
              <div className="space-y-4">
                {workflowRuns.map((run) => (
                  <Card key={run.id} data-testid={`card-run-${run.id}`}>
                    <CardHeader>
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <Badge
                              variant={
                                run.status === "completed"
                                  ? "default"
                                  : run.status === "failed"
                                  ? "destructive"
                                  : "secondary"
                              }
                              data-testid={`badge-run-status-${run.id}`}
                            >
                              {run.status === "completed" && <CheckCircle className="w-3 h-3 mr-1" />}
                              {run.status === "failed" && <XCircle className="w-3 h-3 mr-1" />}
                              {run.status === "running" && <Clock className="w-3 h-3 mr-1" />}
                              {run.status}
                            </Badge>
                            <span className="text-sm text-muted-foreground">
                              Run ID: {run.id.slice(0, 8)}...
                            </span>
                          </div>
                          <div className="flex items-center gap-4 mt-2 text-sm text-muted-foreground">
                            <div className="flex items-center gap-1">
                              <Calendar className="w-3 h-3" />
                              {new Date(run.startedAt).toLocaleString()}
                            </div>
                            {run.completedAt && (
                              <div className="flex items-center gap-1">
                                <Clock className="w-3 h-3" />
                                Duration:{" "}
                                {Math.round(
                                  (new Date(run.completedAt).getTime() -
                                    new Date(run.startedAt).getTime()) /
                                    1000
                                )}
                                s
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <Accordion type="single" collapsible>
                        {run.error && (
                          <AccordionItem value="error">
                            <AccordionTrigger 
                              className="text-destructive"
                              data-testid={`accordion-error-${run.id}`}
                            >
                              <div className="flex items-center gap-2">
                                <AlertCircle className="w-4 h-4" />
                                Error Details
                              </div>
                            </AccordionTrigger>
                            <AccordionContent>
                              <div 
                                className="bg-destructive/10 p-3 rounded-md text-sm"
                                data-testid={`text-error-${run.id}`}
                              >
                                {run.error}
                              </div>
                            </AccordionContent>
                          </AccordionItem>
                        )}
                        {run.input && Object.keys(run.input).length > 0 && (
                          <AccordionItem value="input">
                            <AccordionTrigger data-testid={`accordion-input-${run.id}`}>
                              Input
                            </AccordionTrigger>
                            <AccordionContent>
                              <pre 
                                className="bg-muted p-3 rounded-md text-xs overflow-auto"
                                data-testid={`text-input-${run.id}`}
                              >
                                {JSON.stringify(run.input, null, 2)}
                              </pre>
                            </AccordionContent>
                          </AccordionItem>
                        )}
                        {run.output && Object.keys(run.output).length > 0 && (
                          <AccordionItem value="output">
                            <AccordionTrigger data-testid={`accordion-output-${run.id}`}>
                              Output & Results
                            </AccordionTrigger>
                            <AccordionContent>
                              <div className="space-y-4" data-testid={`text-output-${run.id}`}>
                                {Object.entries(run.output).map(([key, value]: [string, any]) => (
                                  <div key={key} className="space-y-2">
                                    <h4 className="text-sm font-semibold text-muted-foreground capitalize">
                                      {key.replace(/_/g, ' ')}
                                    </h4>

                                    {/* Display AI Chat Response */}
                                    {value?.response && typeof value.response === 'string' && (
                                      <div className="bg-muted p-4 rounded-lg">
                                        <p className="text-sm whitespace-pre-wrap">{value.response}</p>
                                        {value.tokens && (
                                          <p className="text-xs text-muted-foreground mt-2">
                                            Tokens used: {value.tokens}
                                          </p>
                                        )}
                                      </div>
                                    )}

                                    {/* Display Generated Image */}
                                    {value?.imageGenerated && value?.imageUrl && (
                                      <div className="space-y-2">
                                        <img 
                                          src={value.imageUrl} 
                                          alt={value.prompt || 'Generated image'}
                                          className="max-w-full h-auto rounded-lg border"
                                          data-testid={`img-generated-${run.id}`}
                                        />
                                        {value.prompt && (
                                          <p className="text-xs text-muted-foreground">
                                            Prompt: {value.prompt}
                                          </p>
                                        )}
                                      </div>
                                    )}

                                    {/* Display Image Generation Error */}
                                    {value?.imageGenerated === false && value?.error && (
                                      <div className="bg-destructive/10 p-3 rounded-lg">
                                        <p className="text-sm text-destructive">
                                          Image generation failed: {value.error}
                                        </p>
                                        {value.prompt && (
                                          <p className="text-xs text-muted-foreground mt-1">
                                            Prompt: {value.prompt}
                                          </p>
                                        )}
                                      </div>
                                    )}

                                    {/* Display Delay */}
                                    {value?.delayed !== undefined && (
                                      <p className="text-sm text-muted-foreground">
                                        Delayed for {value.delayed} seconds
                                      </p>
                                    )}

                                    {/* Display Webhook Response */}
                                    {value?.status !== undefined && value?.body && (
                                      <div className="bg-muted p-3 rounded-lg">
                                        <p className="text-xs text-muted-foreground mb-1">
                                          Status: {value.status}
                                        </p>
                                        <pre className="text-xs overflow-auto">
                                          {value.body}
                                        </pre>
                                      </div>
                                    )}

                                    {/* Fallback: Show raw JSON for unknown formats */}
                                    {!value?.response && 
                                     value?.imageGenerated === undefined && 
                                     value?.delayed === undefined && 
                                     value?.status === undefined && (
                                      <pre className="bg-muted p-3 rounded-md text-xs overflow-auto">
                                        {JSON.stringify(value, null, 2)}
                                      </pre>
                                    )}
                                  </div>
                                ))}
                              </div>
                            </AccordionContent>
                          </AccordionItem>
                        )}
                      </Accordion>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </ScrollArea>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/components/workflow-editor.ts.content:
import { useState } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { ArrowLeft, Plus, Trash2, MoveUp, MoveDown, Save } from "lucide-react";

type StepType = "ai_chat" | "ai_image_generation" | "delay" | "webhook";

type WorkflowStep = {
  id: string;
  type: StepType;
  config: Record<string, any>;
};

type Workflow = {
  id?: string;
  name: string;
  description: string;
  triggerType: "manual" | "scheduled" | "webhook";
  triggerSchedule: string | null;
  enabled: boolean;
  steps: WorkflowStep[];
};

type AIModel = {
  id: string;
  name: string;
  model: string;
};

type WebhookConfiguration = {
  id: string;
  name: string;
  url: string;
  method: string;
  headers: Record<string, string> | null;
  bodyTemplate: any;
  authType: string | null;
  authConfig: any;
};

export function WorkflowEditor({ workflow, onClose }: { workflow: Workflow | null; onClose: () => void }) {
  const { toast } = useToast();
  const [formData, setFormData] = useState<Workflow>({
    name: workflow?.name || "",
    description: workflow?.description || "",
    triggerType: workflow?.triggerType || "manual",
    triggerSchedule: workflow?.triggerSchedule || null,
    enabled: workflow?.enabled ?? true,
    steps: workflow?.steps || [],
  });

  const { data: models = [] } = useQuery<AIModel[]>({
    queryKey: ["/api/models"],
  });

  const { data: webhooks = [] } = useQuery<WebhookConfiguration[]>({
    queryKey: ["/api/webhooks"],
  });

  const saveMutation = useMutation({
    mutationFn: async (data: Workflow) => {
      if (workflow?.id) {
        return await apiRequest(`/api/workflows/${workflow.id}`, "PATCH", data);
      } else {
        return await apiRequest("/api/workflows", "POST", data);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/workflows"] });
      toast({
        title: workflow?.id ? "Workflow updated" : "Workflow created",
        description: "Your workflow has been saved successfully.",
      });
      onClose();
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to save workflow",
        variant: "destructive",
      });
    },
  });

  const addStep = (type: StepType) => {
    const newStep: WorkflowStep = {
      id: crypto.randomUUID(),
      type,
      config: getDefaultConfig(type),
    };
    setFormData({ ...formData, steps: [...formData.steps, newStep] });
  };

  const removeStep = (index: number) => {
    const newSteps = formData.steps.filter((_, i) => i !== index);
    setFormData({ ...formData, steps: newSteps });
  };

  const moveStep = (index: number, direction: "up" | "down") => {
    const newSteps = [...formData.steps];
    const targetIndex = direction === "up" ? index - 1 : index + 1;
    if (targetIndex >= 0 && targetIndex < newSteps.length) {
      [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];
      setFormData({ ...formData, steps: newSteps });
    }
  };

  const updateStepConfig = (index: number, config: Record<string, any>) => {
    const newSteps = [...formData.steps];
    newSteps[index].config = { ...newSteps[index].config, ...config };
    setFormData({ ...formData, steps: newSteps });
  };

  const getDefaultConfig = (type: StepType): Record<string, any> => {
    switch (type) {
      case "ai_chat":
        return { modelId: "", prompt: "" };
      case "ai_image_generation":
        return { prompt: "" };
      case "delay":
        return { seconds: 5 };
      case "webhook":
        return { 
          webhookConfigId: "",
          url: "", 
          method: "POST", 
          headers: {},
          body: {},
          authType: null,
          authConfig: null,
        };
      default:
        return {};
    }
  };

  const handleSave = () => {
    if (!formData.name.trim()) {
      toast({
        title: "Validation error",
        description: "Please provide a workflow name",
        variant: "destructive",
      });
      return;
    }

    if (formData.steps.length === 0) {
      toast({
        title: "Validation error",
        description: "Please add at least one step",
        variant: "destructive",
      });
      return;
    }

    saveMutation.mutate(formData);
  };

  const getStepIcon = (type: StepType) => {
    switch (type) {
      case "ai_chat":
        return "💬";
      case "ai_image_generation":
        return "🎨";
      case "delay":
        return "⏱️";
      case "webhook":
        return "🔗";
      default:
        return "📝";
    }
  };

  const getStepTitle = (type: StepType) => {
    switch (type) {
      case "ai_chat":
        return "AI Chat";
      case "ai_image_generation":
        return "Image Generation";
      case "delay":
        return "Delay";
      case "webhook":
        return "Webhook";
      default:
        return type;
    }
  };

  return (
    <div className="h-full overflow-auto">
      <div className="max-w-5xl mx-auto p-6 space-y-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" onClick={onClose} data-testid="button-back">
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back
          </Button>
          <h1 className="text-3xl font-bold">
            {workflow?.id ? "Edit Workflow" : "Create Workflow"}
          </h1>
        </div>

        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
            <CardDescription>Configure your workflow's basic settings</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="name">Workflow Name</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="My Awesome Workflow"
                data-testid="input-workflow-name"
              />
            </div>

            <div>
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Describe what this workflow does..."
                rows={3}
                data-testid="input-workflow-description"
              />
            </div>

            <div>
              <Label htmlFor="trigger">Trigger Type</Label>
              <Select
                value={formData.triggerType}
                onValueChange={(value: any) => setFormData({ ...formData, triggerType: value })}
              >
                <SelectTrigger id="trigger" data-testid="select-trigger-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="manual">Manual</SelectItem>
                  <SelectItem value="scheduled">Scheduled</SelectItem>
                  <SelectItem value="webhook">Webhook</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex items-center justify-between">
              <div>
                <Label htmlFor="enabled">Enabled</Label>
                <p className="text-sm text-muted-foreground">
                  Enable or disable this workflow
                </p>
              </div>
              <Switch
                id="enabled"
                checked={formData.enabled}
                onCheckedChange={(checked) => setFormData({ ...formData, enabled: checked })}
                data-testid="switch-enabled"
              />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div>
                <CardTitle>Workflow Steps</CardTitle>
                <CardDescription>Add and configure the steps in your workflow</CardDescription>
              </div>
              <div className="flex gap-2">
                <Select onValueChange={(type: StepType) => addStep(type)}>
                  <SelectTrigger className="w-[180px]" data-testid="select-add-step">
                    <SelectValue placeholder="Add step..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ai_chat">AI Chat</SelectItem>
                    <SelectItem value="ai_image_generation">Image Generation</SelectItem>
                    <SelectItem value="delay">Delay</SelectItem>
                    <SelectItem value="webhook">Webhook</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            {formData.steps.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                No steps added yet. Click "Add step..." to get started.
              </div>
            ) : (
              formData.steps.map((step, index) => (
                <Card key={step.id} data-testid={`card-step-${index}`}>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="text-2xl">{getStepIcon(step.type)}</span>
                        <div>
                          <CardTitle className="text-lg">
                            Step {index + 1}: {getStepTitle(step.type)}
                          </CardTitle>
                          <Badge variant="secondary" className="mt-1">
                            {step.type}
                          </Badge>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="icon"
                          variant="ghost"
                          onClick={() => moveStep(index, "up")}
                          disabled={index === 0}
                          data-testid={`button-move-up-${index}`}
                        >
                          <MoveUp className="w-4 h-4" />
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          onClick={() => moveStep(index, "down")}
                          disabled={index === formData.steps.length - 1}
                          data-testid={`button-move-down-${index}`}
                        >
                          <MoveDown className="w-4 h-4" />
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          onClick={() => removeStep(index)}
                          data-testid={`button-remove-step-${index}`}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {step.type === "ai_chat" && (
                      <>
                        <div>
                          <Label>AI Model</Label>
                          <Select
                            value={step.config.modelId}
                            onValueChange={(value) => updateStepConfig(index, { modelId: value })}
                          >
                            <SelectTrigger data-testid={`select-model-${index}`}>
                              <SelectValue placeholder="Select a model..." />
                            </SelectTrigger>
                            <SelectContent>
                              {models.map((model) => (
                                <SelectItem key={model.id} value={model.id}>
                                  {model.name}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                        <div>
                          <Label>Prompt</Label>
                          <Textarea
                            value={step.config.prompt}
                            onChange={(e) => updateStepConfig(index, { prompt: e.target.value })}
                            placeholder="Enter your prompt... Use {{variable}} for context"
                            rows={4}
                            data-testid={`input-prompt-${index}`}
                          />
                          <p className="text-xs text-muted-foreground mt-1">
                            Use &#123;&#123;step_1_result.response&#125;&#125; to reference previous steps
                          </p>
                        </div>
                      </>
                    )}

                    {step.type === "ai_image_generation" && (
                      <div>
                        <Label>Prompt</Label>
                        <Textarea
                          value={step.config.prompt}
                          onChange={(e) => updateStepConfig(index, { prompt: e.target.value })}
                          placeholder="Describe the image to generate..."
                          rows={3}
                          data-testid={`input-prompt-${index}`}
                        />
                      </div>
                    )}

                    {step.type === "delay" && (
                      <div>
                        <Label>Delay (seconds)</Label>
                        <Input
                          type="number"
                          value={step.config.seconds}
                          onChange={(e) => updateStepConfig(index, { seconds: parseInt(e.target.value) || 0 })}
                          min={1}
                          data-testid={`input-delay-${index}`}
                        />
                      </div>
                    )}

                    {step.type === "webhook" && (
                      <>
                        <div>
                          <Label>Saved Webhook (Optional)</Label>
                          <Select
                            value={step.config.webhookConfigId || ""}
                            onValueChange={(value) => {
                              if (value === "custom") {
                                updateStepConfig(index, { 
                                  webhookConfigId: "",
                                  url: "",
                                  method: "POST",
                                  headers: {},
                                  body: {},
                                  authType: null,
                                  authConfig: null,
                                });
                              } else {
                                const webhook = webhooks.find(w => w.id === value);
                                if (webhook) {
                                  // Only store the webhook config ID and basic display info
                                  // Auth credentials will be fetched at runtime for security
                                  updateStepConfig(index, { 
                                    webhookConfigId: webhook.id,
                                    url: webhook.url,
                                    method: webhook.method,
                                    headers: webhook.headers || {},
                                    body: webhook.bodyTemplate || {},
                                    authType: webhook.authType,
                                    // Do NOT store authConfig - will be loaded at runtime
                                    authConfig: null,
                                  });
                                }
                              }
                            }}
                          >
                            <SelectTrigger data-testid={`select-webhook-config-${index}`}>
                              <SelectValue placeholder="Select saved webhook or custom..." />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="custom">Custom Configuration</SelectItem>
                              {webhooks.map((webhook) => (
                                <SelectItem key={webhook.id} value={webhook.id}>
                                  {webhook.name}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          {webhooks.length === 0 && (
                            <p className="text-xs text-muted-foreground mt-1">
                              No saved webhooks. Go to Webhooks page to create reusable configurations.
                            </p>
                          )}
                        </div>

                        {!step.config.webhookConfigId && (
                          <>
                            <div>
                              <Label>URL</Label>
                              <Input
                                value={step.config.url}
                                onChange={(e) => updateStepConfig(index, { url: e.target.value })}
                                placeholder="https://api.example.com/webhook"
                                data-testid={`input-url-${index}`}
                              />
                            </div>
                            <div>
                              <Label>Method</Label>
                              <Select
                                value={step.config.method}
                                onValueChange={(value) => updateStepConfig(index, { method: value })}
                              >
                                <SelectTrigger data-testid={`select-method-${index}`}>
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="GET">GET</SelectItem>
                                  <SelectItem value="POST">POST</SelectItem>
                                  <SelectItem value="PUT">PUT</SelectItem>
                                  <SelectItem value="PATCH">PATCH</SelectItem>
                                </SelectContent>
                              </Select>
                            </div>
                            <div>
                              <Label>Headers (JSON)</Label>
                              <Textarea
                                value={typeof step.config.headers === 'string' ? step.config.headers : JSON.stringify(step.config.headers || {}, null, 2)}
                                onChange={(e) => {
                                  try {
                                    const parsed = JSON.parse(e.target.value);
                                    updateStepConfig(index, { headers: parsed });
                                  } catch {
                                    updateStepConfig(index, { headers: e.target.value });
                                  }
                                }}
                                placeholder='{"Content-Type": "application/json"}'
                                className="font-mono text-sm"
                                rows={3}
                                data-testid={`input-headers-${index}`}
                              />
                            </div>
                            <div>
                              <Label>Body Template (JSON)</Label>
                              <Textarea
                                value={typeof step.config.body === 'string' ? step.config.body : JSON.stringify(step.config.body || {}, null, 2)}
                                onChange={(e) => {
                                  try {
                                    const parsed = JSON.parse(e.target.value);
                                    updateStepConfig(index, { body: parsed });
                                  } catch {
                                    updateStepConfig(index, { body: e.target.value });
                                  }
                                }}
                                placeholder='{"message": "{{step_1_result.response}}"}'
                                className="font-mono text-sm"
                                rows={4}
                                data-testid={`input-body-${index}`}
                              />
                              <p className="text-xs text-muted-foreground mt-1">
                                Use &#123;&#123;step_X_result&#125;&#125; to reference previous step outputs
                              </p>
                            </div>
                          </>
                        )}

                        {step.config.webhookConfigId && (
                          <div className="rounded-lg bg-muted p-4">
                            <div className="text-sm font-medium mb-2">Configuration Preview</div>
                            <div className="space-y-1 text-sm">
                              <div className="flex gap-2">
                                <span className="text-muted-foreground">Method:</span>
                                <Badge variant="outline">{step.config.method}</Badge>
                              </div>
                              <div>
                                <span className="text-muted-foreground">URL:</span>
                                <code className="ml-2 text-xs bg-background px-2 py-0.5 rounded">
                                  {step.config.url}
                                </code>
                              </div>
                              {step.config.authType && (
                                <div className="flex gap-2">
                                  <span className="text-muted-foreground">Auth:</span>
                                  <Badge variant="secondary">{step.config.authType}</Badge>
                                </div>
                              )}
                            </div>
                            <p className="text-xs text-muted-foreground mt-2">
                              Using saved webhook configuration. Variables in body template will be replaced at runtime.
                            </p>
                          </div>
                        )}
                      </>
                    )}
                  </CardContent>
                </Card>
              ))
            )}
          </CardContent>
        </Card>

        <div className="flex justify-end gap-2">
          <Button variant="outline" onClick={onClose} data-testid="button-cancel">
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saveMutation.isPending} data-testid="button-save">
            <Save className="w-4 h-4 mr-2" />
            {saveMutation.isPending ? "Saving..." : "Save Workflow"}
          </Button>
        </div>
      </div>
    </div>
  );
}

server/workflowEngine.ts.content:
import { storage } from "./storage";
import type { Workflow, WorkflowRun } from "@shared/schema";
import OpenAI from "openai";
import { geminiService } from "./services/geminiService";
import { imageStore } from "./services/imageStore";
import { checkImagePrompt } from "./utils/contentFilter";

type WorkflowStep = {
  id: string;
  type: "ai_chat" | "ai_image_generation" | "webhook" | "delay";
  config: any;
};

export class WorkflowEngine {
  async executeWorkflow(workflowId: string, userId: string, input?: any): Promise<WorkflowRun> {
    const workflow = await storage.getWorkflow(userId, workflowId);
    if (!workflow) {
      throw new Error("Workflow not found");
    }

    if (!workflow.enabled) {
      throw new Error("Workflow is disabled");
    }

    const run = await storage.createWorkflowRun({
      workflowId,
      userId,
      status: "running",
      input: input || {},
      output: {},
      error: null,
      completedAt: null,
    });

    console.log(`[Workflow] Created run with ID: ${run.id}`);

    try {
      const steps = (workflow.steps as WorkflowStep[]) || [];
      let context: any = { ...input };

      for (let i = 0; i < steps.length; i++) {
        const step = steps[i];
        console.log(`[Workflow] Executing step ${i + 1}/${steps.length}: ${step.type}`);

        try {
          const stepResult = await this.executeStep(step, context, userId);
          context = { ...context, [`step_${i + 1}_result`]: stepResult };
        } catch (error: any) {
          console.error(`[Workflow] Step ${i + 1} failed:`, error.message);
          const failed = await storage.updateWorkflowRun(run.id, {
            status: "failed",
            error: `Step ${i + 1} (${step.type}) failed: ${error.message}`,
            output: context,
            completedAt: new Date(),
          });
          // Return the failed run instead of throwing
          console.log(`[Workflow] Step failed. Returning run:`, failed?.id, failed?.status);
          return failed || run;
        }
      }

      const updated = await storage.updateWorkflowRun(run.id, {
        status: "completed",
        output: context,
        completedAt: new Date(),
      });

      console.log(`[Workflow] Workflow completed. Returning run:`, updated?.id, updated?.status);
      return updated || run;
    } catch (error: any) {
      // Handle unexpected errors (not step failures)
      console.error("[Workflow] Execution failed:", error);
      const failed = await storage.updateWorkflowRun(run.id, {
        status: "failed",
        error: error.message || "Unexpected error during workflow execution",
        completedAt: new Date(),
      });
      console.log(`[Workflow] Unexpected error. Returning run:`, failed?.id, failed?.status);
      return failed || run;
    }
  }

  private async executeStep(step: WorkflowStep, context: any, userId: string): Promise<any> {
    switch (step.type) {
      case "ai_chat":
        return await this.executeAIChat(step, context, userId);

      case "ai_image_generation":
        return await this.executeImageGeneration(step, context, userId);

      case "delay":
        return await this.executeDelay(step);

      case "webhook":
        return await this.executeWebhook(step, context, userId);

      default:
        throw new Error(`Unsupported step type: ${step.type}`);
    }
  }

  private async executeAIChat(step: WorkflowStep, context: any, userId: string): Promise<any> {
    const { modelId, prompt } = step.config;
    const resolvedPrompt = this.resolveVariables(prompt, context);

    const model = await storage.getAIModel(userId, modelId);
    if (!model) {
      throw new Error(`Model ${modelId} not found`);
    }

    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) {
      throw new Error("OpenAI API key not configured");
    }

    const openai = new OpenAI({ apiKey });

    // Use max_completion_tokens for newer reasoning models
    const reasoningModels = ['gpt-5', 'gpt-5-mini', 'gpt-5-nano', 'o1', 'o3', 'o1-mini', 'o1-preview', 'o3-mini'];
    const isReasoningModel = reasoningModels.some(m => model.model.toLowerCase().includes(m));

    const requestParams: any = {
      model: model.model,
      messages: [],
    };

    // Reasoning models don't support system messages or temperature
    if (isReasoningModel) {
      // Combine system prompt with user message for reasoning models
      const combinedPrompt = model.systemPrompt 
        ? `${model.systemPrompt}\n\n${resolvedPrompt}`
        : resolvedPrompt;
      requestParams.messages.push({ role: "user", content: combinedPrompt });
      // Reasoning models need much higher token limits (they use tokens for thinking)
      // Use at least 4x the configured tokens, minimum 2000
      requestParams.max_completion_tokens = Math.max(model.maxTokens * 4, 2000);
    } else {
      // Standard models support system messages and temperature
      requestParams.messages.push(
        { role: "system", content: model.systemPrompt },
        { role: "user", content: resolvedPrompt }
      );
      requestParams.temperature = model.temperature / 100;
      requestParams.max_tokens = model.maxTokens;
    }

    console.log("[Workflow] OpenAI request params:", JSON.stringify(requestParams, null, 2));

    const response = await openai.chat.completions.create(requestParams);

    console.log("[Workflow] Full OpenAI response:", JSON.stringify(response, null, 2));

    return {
      response: response.choices[0]?.message?.content || "",
      tokens: response.usage?.total_tokens || 0,
    };
  }

  private async executeImageGeneration(step: WorkflowStep, context: any, userId: string): Promise<any> {
    const { prompt } = step.config;
    const resolvedPrompt = this.resolveVariables(prompt, context);

    // Check content filter
    const filterResult = checkImagePrompt(resolvedPrompt);
    if (!filterResult.allowed) {
      console.log("[Workflow] Image generation blocked:", filterResult.reason);
      return {
        prompt: resolvedPrompt,
        imageGenerated: false,
        error: filterResult.reason || "Content blocked",
      };
    }

    try {
      const { imageData } = await geminiService.generateImage(resolvedPrompt);

      // Save the generated image to storage with error handling
      const imageResult = await imageStore.store(imageData, userId, "generated", resolvedPrompt);

      return {
        prompt: resolvedPrompt,
        imageGenerated: true,
        imageUrl: imageResult.publicUrl,
        size: imageData.length,
      };
    } catch (error: any) {
      console.error("[Workflow] Image generation failed:", error);
      return {
        prompt: resolvedPrompt,
        imageGenerated: false,
        error: error.message || "Failed to generate or store image",
      };
    }
  }

  private async executeDelay(step: WorkflowStep): Promise<any> {
    const { seconds } = step.config;
    await new Promise(resolve => setTimeout(resolve, seconds * 1000));
    return { delayed: seconds };
  }

  private async executeWebhook(step: WorkflowStep, context: any, userId?: string): Promise<any> {
    let { url, method = "POST", headers = {}, body, authType, authConfig, webhookConfigId } = step.config;

    // If using a saved webhook configuration, fetch auth credentials at runtime
    if (webhookConfigId && userId) {
      try {
        const savedWebhook = await storage.getWebhookConfiguration(userId, webhookConfigId);
        if (savedWebhook) {
          // Override with saved configuration including auth credentials
          url = savedWebhook.url;
          method = savedWebhook.method;
          headers = savedWebhook.headers as Record<string, string> || {};
          body = savedWebhook.bodyTemplate;
          authType = savedWebhook.authType;
          authConfig = savedWebhook.authConfig;
        }
      } catch (error) {
        console.error("[Workflow] Failed to fetch saved webhook configuration:", error);
        // Continue with step config as fallback
      }
    }

    // SSRF protection: Validate webhook URL
    try {
      const urlObj = new URL(url);
      const hostname = urlObj.hostname.toLowerCase();

      // Block localhost, private IPs, and internal networks
      const blockedHosts = [
        'localhost', '127.0.0.1', '0.0.0.0',
        '::1', '::ffff:127.0.0.1',
      ];

      if (blockedHosts.includes(hostname) || 
          hostname.startsWith('10.') ||
          hostname.startsWith('192.168.') ||
          hostname.match(/^172\.(1[6-9]|2[0-9]|3[0-1])\./) ||
          hostname.endsWith('.local')) {
        throw new Error("Cannot execute webhooks pointing to internal networks");
      }
    } catch (error: any) {
      throw new Error(`Invalid webhook URL: ${error.message}`);
    }

    // Prepare headers with authentication
    const requestHeaders: Record<string, string> = {
      "Content-Type": "application/json",
      ...headers,
    };

    // Add authentication if configured
    if (authType === "bearer" && authConfig) {
      const token = (authConfig as any).token;
      if (token) {
        requestHeaders["Authorization"] = `Bearer ${token}`;
      }
    } else if (authType === "api_key" && authConfig) {
      const { key, value } = authConfig as any;
      if (key && value) {
        requestHeaders[key] = value;
      }
    }

    // Resolve variables in body template (safely)
    let resolvedBody = body;
    if (typeof body === 'object') {
      resolvedBody = this.resolveVariables(JSON.stringify(body), context);
    } else if (typeof body === 'string') {
      resolvedBody = this.resolveVariables(body, context);
    }

    const response = await fetch(url, {
      method,
      headers: requestHeaders,
      body: method !== "GET" ? resolvedBody : undefined,
    });

    // Return sanitized result - DO NOT include auth credentials in response
    return {
      status: response.status,
      statusText: response.statusText,
      body: await response.text(),
      // Do not return: authType, authConfig, headers with auth tokens
    };
  }

  private resolveVariables(text: string, context: any): string {
    if (!text) return "";

    let resolved = text;
    const matches = text.match(/\{\{([^}]+)\}\}/g);

    if (matches) {
      matches.forEach(match => {
        const variable = match.replace(/\{\{|\}\}/g, "").trim();

        // Sanitize variable name to prevent prototype pollution
        if (variable.includes('__proto__') || variable.includes('constructor') || variable.includes('prototype')) {
          resolved = resolved.replace(match, '');
          return;
        }

        const value = this.getNestedValue(context, variable);

        // Convert value to string safely
        let stringValue = '';
        if (value !== null && value !== undefined) {
          // Prevent injection by escaping special characters in JSON context
          if (typeof value === 'string') {
            stringValue = value;
          } else if (typeof value === 'object') {
            stringValue = JSON.stringify(value);
          } else {
            stringValue = String(value);
          }
        }

        resolved = resolved.replace(match, stringValue);
      });
    }

    return resolved;
  }

  private getNestedValue(obj: any, path: string): any {
    // Prevent prototype pollution attacks
    const keys = path.split(".");
    let current = obj;

    for (const key of keys) {
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
        return undefined;
      }
      if (current === null || current === undefined) {
        return undefined;
      }
      current = current[key];
    }

    return current;
  }
}

export const workflowEngine = new WorkflowEngine();

